     */
    monochrome?: boolean;
  }

  let {
    providerId: providerRef,
    class: className = 'size-3.5',
    size = 14,
    monochrome = false,
  }: Props = $props();
  // A named profile (§5.54 `<base>@<id>`) shares its base provider's icon.
  const providerId = $derived(providerRefBaseId(providerRef));
